106|   for (;;)
107|   {
108|      png_uint_32 length = png_read_chunk_header(png_ptr);
109|      png_uint_32 chunk_name = png_ptr->chunk_name;
110|
111|      /* IDAT logic needs to happen here to simplify getting the two flags
112|       * right.
