4103|      /* The following checks just the 'row_stride' calculation to ensure it
4104|       * fits in a signed 32-bit value.  Because channels/components can be
4105|       * either 1 or 2 bytes in size the length of a row can still overflow 32
4106|       * bits; this is just to verify that the 'row_stride' argument can be
4107|       * represented.
4108|       */
4109|      if (image->width <= 0x7fffffffU/channels) /* no overflow */
4110|      {
4111|         png_uint_32 check;
4112|         const png_uint_32 png_row_stride = image->width * channels;
4113|
4114|         if (row_stride == 0)
4115|            row_stride = (png_int_32)/*SAFE*/png_row_stride;
4116|
4117|         if (row_stride < 0)
4118|            check = (png_uint_32)(-row_stride);
4119|
4120|         else
4121|            check = (png_uint_32)row_stride;
