965|   if (length > 3*PNG_MAX_PALETTE_LENGTH || length % 3)
966|   {
967|      png_crc_finish(png_ptr, length);
968|
969|      if (png_ptr->color_type != PNG_COLOR_TYPE_PALETTE)
970|         png_chunk_benign_error(png_ptr, "invalid");
971|
972|      else
