999|      png_crc_read(png_ptr, buf, 3);
1000|      pal_ptr->red = buf[0];
1001|      pal_ptr->green = buf[1];
1002|      pal_ptr->blue = buf[2];
1003|   }
1004|#else
1005|   for (i = 0; i < num; i++)
1006|   {
1007|      png_byte buf[3];
1008|
1009|      png_crc_read(png_ptr, buf, 3);
1010|      /* Don't depend upon png_color being any order */
