680|      exit(1);
681|   }
682|
683|   d->info_ptr = png_create_info_struct(d->png_ptr);
684|   d->end_ptr = png_create_info_struct(d->png_ptr);
685|   if (d->info_ptr == NULL || d->end_ptr == NULL)
