5223|               dp->red_sBIT = sBIT->red;
5224|
5225|            if (sBIT->green == 0 || sBIT->green > dp->bit_depth)
5226|               sBIT_invalid = 1;
5227|            else
5228|               dp->green_sBIT = sBIT->green;
5229|
5230|            if (sBIT->blue == 0 || sBIT->blue > dp->bit_depth)
5231|               sBIT_invalid = 1;
5232|            else
5233|               dp->blue_sBIT = sBIT->blue;
5234|         }
