1511|
1512|#  define CHUNK(a,b,c,d) (((a)<<24)+((b)<<16)+((c)<<8)+(d))
1513|
1514|   switch (chunk)
1515|   {
1516|      case CHUNK(105,67,67,80):  /* iCCP */
1517|         if (nparams == 2)
1518|            return make_insert(what, insert_iCCP, nparams, parameter_list);
1519|         break;
1520|
