1522|         if (nparams == 2)
1523|            return make_insert(what, insert_tEXt, nparams, parameter_list);
1524|         break;
1525|
1526|      case CHUNK(122,84,88,116): /* zTXt */
1527|         if (nparams == 2)
1528|            return make_insert(what, insert_zTXt, nparams, parameter_list);
1529|         break;
1530|
1531|      case CHUNK(105,84,88,116): /* iTXt */
1532|         if (nparams == 4)
