1534|         break;
1535|
1536|      case CHUNK(104,73,83,84):  /* hIST */
1537|         if (nparams <= 256)
1538|            return make_insert(what, insert_hIST, nparams, parameter_list);
1539|         break;
1540|
1541|      case CHUNK(115,66,73,84): /* sBIT */
